var constants_default = "# Names of option values, as in `tkinter.constants` of CPython.\nNO = FALSE = OFF = 0\nYES = TRUE = ON = 1\n\nN = \"n\"\nS = \"s\"\nW = \"w\"\nE = \"e\"\nNW = \"nw\"\nSW = \"sw\"\nNE = \"ne\"\nSE = \"se\"\nNS = \"ns\"\nEW = \"ew\"\nNSEW = \"nsew\"\nCENTER = \"center\"\n\nNONE = \"none\"\nX = \"x\"\nY = \"y\"\nBOTH = \"both\"\n\nLEFT = \"left\"\nTOP = \"top\"\nRIGHT = \"right\"\nBOTTOM = \"bottom\"\n\nRAISED = \"raised\"\nSUNKEN = \"sunken\"\nFLAT = \"flat\"\nRIDGE = \"ridge\"\nGROOVE = \"groove\"\nSOLID = \"solid\"\n\nHORIZONTAL = \"horizontal\"\nVERTICAL = \"vertical\"\n\nNUMERIC = \"numeric\"\nCHAR = \"char\"\nWORD = \"word\"\n\nBASELINE = \"baseline\"\nINSIDE = \"inside\"\nOUTSIDE = \"outside\"\n\nSEL = \"sel\"\nSEL_FIRST = \"sel.first\"\nSEL_LAST = \"sel.last\"\nEND = \"end\"\nINSERT = \"insert\"\nCURRENT = \"current\"\nANCHOR = \"anchor\"\nALL = \"all\"\n\nNORMAL = \"normal\"\nDISABLED = \"disabled\"\nACTIVE = \"active\"\nHIDDEN = \"hidden\"\nREADONLY = \"readonly\"\n\nCASCADE = \"cascade\"\nCHECKBUTTON = \"checkbutton\"\nCOMMAND = \"command\"\nRADIOBUTTON = \"radiobutton\"\nSEPARATOR = \"separator\"\n\nSINGLE = \"single\"\nBROWSE = \"browse\"\nMULTIPLE = \"multiple\"\nEXTENDED = \"extended\"\n\nDOTBOX = \"dotbox\"\nUNDERLINE = \"underline\"\n\nPIESLICE = \"pieslice\"\nCHORD = \"chord\"\nARC = \"arc\"\nFIRST = \"first\"\nLAST = \"last\"\nBUTT = \"butt\"\nPROJECTING = \"projecting\"\nROUND = \"round\"\nBEVEL = \"bevel\"\nMITER = \"miter\"\n\nMOVETO = \"moveto\"\nSCROLL = \"scroll\"\nUNITS = \"units\"\nPAGES = \"pages\"\n";
